mapper.insert:
insert into sys_role_permission (role_id, permission_id, tenant_id)
select role_id, permission_id, #{targetTenantId}
from sys_role_permission
where tenant_id = #{sourceTenantId}

mapper.select:
select count(1)
from sys_user_tenant
where user_id = #{userId}
  and tenant_id = #{tenantId}

mapper.insert:
insert into sys_invitation (
  id, token_hash, tenant_id, role_id, created_by, expires_at, used_at, created_at, updated_at
) values (
  #{id}, #{tokenHash}, #{tenantId}, #{roleId}, #{createdBy}, #{expiresAt}, #{usedAt}, #{createdAt}, #{updatedAt}
)

mapper.update:
update sys_invitation
set used_at = #{usedAt}, updated_at = #{usedAt}
where id = #{invitationId}
  and used_at is null
  and expires_at > #{usedAt}

mapper.select:
select u.id, u.username, u.display_name, u.role_id, r.code role_code, r.name role_name, u.enabled, u.created_at
from sys_user u inner join sys_role r on r.id = u.role_id
where u.deleted = 0
  and exists (select 1 from sys_user_tenant ut where ut.user_id = u.id and ut.tenant_id = #{tenantId})
and (u.username like concat('%', #{keyword}, '%') or u.display_name like concat('%', #{keyword}, '%'))
and u.role_id = #{roleId}
and u.enabled = #{enabled}
order by u.created_at desc, u.id
limit #{offset}, #{pageSize}

select count(1) from sys_user u where u.deleted = 0
  and exists (select 1 from sys_user_tenant ut where ut.user_id = u.id and ut.tenant_id = #{tenantId})
and (u.username like concat('%', #{keyword}, '%') or u.display_name like concat('%', #{keyword}, '%'))
and u.role_id = #{roleId}
and u.enabled = #{enabled}
